#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    int n, q;
    cin >> n >> q;
    vector<pair<int, int>> painters(q);

    for (int i = 0; i < q; ++i) {
        cin >> painters[i].first >> painters[i].second;
    }

    int maxPaintedSections = 0;

    for (int i = 0; i < q; ++i) {
        for (int j = i + 1; j < q; ++j) {
            vector<int> coverage(n + 1, 0);

            for (int k = 0; k < q; ++k) {
                if (k != i && k != j) {
                    for (int x = painters[k].first; x <= painters[k].second; ++x) {
                        coverage[x] = 1;
                    }
                }
            }

            int paintedSections = 0;
            for (int x = 1; x <= n; ++x) {
                if (coverage[x]) {
                    paintedSections++;
                }
            }
            maxPaintedSections = max(maxPaintedSections, paintedSections);
        }
    }

    cout << maxPaintedSections << endl;
    return 0;
}

